```js
'use strict';

const axios = require('axios');
const { HttpsProxyAgent } = require('https-proxy-agent');

async function testProxy() {
  const targetUrl = 'https://www.google.com';
  const proxyUrl = 'http://127.0.0.1:10808';
  const proxyAgent = new HttpsProxyAgent(proxyUrl);

  console.log(`[测试开始] 准备通过代理 ${proxyUrl} 访问 ${targetUrl}`);

  try {
    const response = await axios.get(targetUrl, {
      httpsAgent: proxyAgent,
      httpAgent: proxyAgent, // 确保 http 和 https 都走代理
      timeout: 15000, // 设置15秒超时
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/108.0.0.0 Safari/537.36'
      }
    });

    if (response.status === 200) {
      console.log(`✅ [测试成功] 代理工作正常！成功访问 ${targetUrl}，状态码: ${response.status}`);
    } else {
      console.warn(`⚠️ [测试异常] 代理似乎工作，但目标网站返回异常状态码: ${response.status}`);
    }

  } catch (error) {
    console.error(`❌ [测试失败] 无法通过代理访问目标网站。`);
    console.error(`  - 错误代码: ${error.code}`);
    console.error(`  - 错误信息: ${error.message}`);
    console.error(`  - 请确认您的代理软件正在运行，并且监听在 ${proxyUrl}`);
  }
}

testProxy();
```

